-- name: by_schema
-- dialect: teradata
LOCKING ROW FOR ACCESS
SELECT TRIM(t.DatabaseName) AS schema_name, TRIM(t.TableName) AS object_name, CASE TRIM(t.TableKind) WHEN 'T' THEN 'TABLE' WHEN 'O' THEN 'TABLE' WHEN 'V' THEN 'VIEW' WHEN 'M' THEN 'MACRO' WHEN 'P' THEN 'PROCEDURE' WHEN 'E' THEN 'PROCEDURE' WHEN 'G' THEN 'TRIGGER' WHEN 'F' THEN 'FUNCTION' WHEN 'R' THEN 'FUNCTION' WHEN 'I' THEN 'JOIN INDEX' WHEN 'N' THEN 'JOIN INDEX' ELSE TRIM(t.TableKind) END AS object_type, TRIM(t.TableKind) AS table_kind, t.CreateTimeStamp AS created, t.CommentString AS comment FROM DBC.TablesV t WHERE UPPER(TRIM(t.DatabaseName)) = UPPER(TRIM(COALESCE(:schema_name, DATABASE))) AND UPPER(TRIM(t.DatabaseName)) NOT IN ('DBC', 'SYSUDTLIB', 'SYSLIB', 'TD_SYSFNLIB', 'SYSSPATIAL', 'SYSBAR', 'LOCKLOGSHREDDER', 'SQLJ', 'TDSTATS', 'TD_SERVER_DB', 'CRASHDUMPS') AND TRIM(t.TableKind) IN ('T', 'O', 'V', 'M', 'P', 'E', 'G', 'F', 'R', 'I', 'N') AND (:object_name IS NULL OR UPPER(TRIM(t.TableName)) = UPPER(TRIM(:object_name))) ORDER BY schema_name, object_type, object_name;
